import{M as e,O as t,c as n,d as r,h as i,m as a,p as o}from"./runtime-core.esm-bundler-jC72uHyJ.js";import{t as s}from"./app-C1WwKQnH.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S05/S05E04.html","title":"S05E04 The One Where Phoebe Hates PBS","lang":"zh-CN","frontmatter":{"title":"S05E04 The One Where Phoebe Hates PBS","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":101},"git":{"createdTime":1780654155000,"updatedTime":1785479208000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":4}]},"readingTime":{"minutes":35.43,"words":10629},"filePathRelative":"语言/英语/Friends老友记/S05/S05E04.md"}`),l={name:`S05E04.md`};function u(s,c,l,u,d,f){let p=e(`StickyAudio`),m=e(`AudioButton`);return t(),r(`div`,null,[i(p,{src:`/audio/friends-tv/S05/S05E04.mp3`,title:`S05E04 The One Where Phoebe Hates PBS`}),c[0]||=o(`<h1 id="the-one-where-phoebe-hates-pbs" tabindex="-1"><a class="header-anchor" href="#the-one-where-phoebe-hates-pbs"><span>The One Where Phoebe Hates PBS</span></a></h1><blockquote><p><em>菲比讨厌PBS的那个</em></p></blockquote><p>The One Where Phoebe Hates PBS</p><blockquote><p>菲比讨厌PBS的那个</p></blockquote><p><strong>Written by: Michael Curtis</strong></p><blockquote><p>作者：迈克尔·柯蒂斯</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Rachel has just gotten home and is going through the mail. She finds something that&#39;s Monica&#39;s and goes over and knocks on her closed bedroom door.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，瑞秋刚到家，正在看邮件。她找到了莫妮卡的东西，走过去敲她关着的卧室门。</em></p></blockquote>`,11),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`0.0`,duration:`3.696`}),c[1]||=a(),c[2]||=n(`strong`,null,`Monica Geller:`,-1),c[3]||=a(` (In a sexy voice) Come in. I've been waiting for you.`,-1),c[4]||=n(`blockquote`,null,[n(`p`,null,`（用性感的声音）进来。我一直在等你。`)],-1),c[5]||=n(`p`,null,[n(`em`,null,`(Rachel enters.)`)],-1),c[6]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（瑞秋进来了。）`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`3.696`,duration:`6.552`}),c[7]||=a(),c[8]||=n(`strong`,null,`Rachel Green:`,-1),c[9]||=a(` Hi! I just wanna-(sees Monica)-Ahhh!!! Oh my God! (She runs out in horror.) Oh my God!`,-1),c[10]||=n(`blockquote`,null,[n(`p`,null,`嗨！我只想-（见莫妮卡）-啊哈！！！哦，我的上帝！（她惊恐地跑了出来。）哦，天哪！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`10.248`,duration:`7.416`}),c[11]||=a(),c[12]||=n(`strong`,null,`Monica Geller:`,-1),c[13]||=a(` (pulling on a robe) Okay, I'm sorry! I'm sorry! I-I-I was um, I was taking a nap.`,-1),c[14]||=n(`blockquote`,null,[n(`p`,null,`（穿上长袍）好吧，对不起！我很抱歉！我，我，我在小睡一会儿。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`17.664`,duration:`9.408`}),c[15]||=a(),c[16]||=n(`strong`,null,`Rachel Green:`,-1),c[17]||=a(` Since when do take naps in that position. Oh God Monica, tell me you were waiting for a guy! Please tell me you were waiting for a guy!`,-1),c[18]||=n(`blockquote`,null,[n(`p`,null,`从什么时候开始，你用那种姿势打盹。天哪，莫妮卡，告诉我你在等一个人！请告诉我你在等一个人！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`27.072`,duration:`10.416`}),c[19]||=a(),c[20]||=n(`strong`,null,`Monica Geller:`,-1),c[21]||=a(` Yes. Yes, I was. A guy. From work. (Thinks) I'm seeing a guy from work! Ha!`,-1),c[22]||=n(`blockquote`,null,[n(`p`,null,`是的。是的，我是。一个人。从工作中。（想）我要去看一个下班的家伙！哈`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`37.488`,duration:`5.424`}),c[23]||=a(),c[24]||=n(`strong`,null,`Rachel Green:`,-1),c[25]||=a(` (Gasps) That cute waiter guy from your restaurant, the one that looks like a non-threatening Ray Liotta?`,-1),c[26]||=n(`blockquote`,null,[n(`p`,null,`（喘息）你们餐厅那个可爱的服务员，看起来像个没有威胁的雷·利奥塔？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`42.912`,duration:`2.184`}),c[27]||=a(),c[28]||=n(`strong`,null,`Monica Geller:`,-1),c[29]||=a(` Uh-huh, that one!`,-1),c[30]||=n(`blockquote`,null,[n(`p`,null,`嗯，那个！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`45.096`,duration:`11.592`}),c[31]||=a(),c[32]||=n(`strong`,null,`Rachel Green:`,-1),c[33]||=a(` Y'know what, just give me a second and I'll be out of your hair. I'm just gonna grab a jacket. When I get back, I want every little detail. (There's a knock on the door.) Maybe that's him. (Goes to answer the door.)`,-1),c[34]||=n(`blockquote`,null,[n(`p`,null,`你知道吗，只要给我一秒钟，我就不烦你了。我去拿件夹克。当我回来的时候，我想要每一个细节。（有人敲门）也许是他。（去开门。）`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`56.688`,duration:`5.112`}),c[35]||=a(),c[36]||=n(`strong`,null,`Monica Geller:`,-1),c[37]||=a(` (Panicking) Okay, umm, okay, umm… (Rachel opens the door.) It's just Joey and Ross.`,-1),c[38]||=n(`blockquote`,null,[n(`p`,null,`（惊慌失措）好吧，嗯，好吧，嗯…（瑞秋开门）只有乔伊和罗斯。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`61.8`,duration:`2.4`}),c[39]||=a(),c[40]||=n(`strong`,null,`Rachel Green:`,-1),c[41]||=a(` Why aren't you guys at the movie?`,-1),c[42]||=n(`blockquote`,null,[n(`p`,null,`你们为什么不去看电影？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`64.2`,duration:`5.952`}),c[43]||=a(),c[44]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[45]||=a(` Well, we were! But Ross was talking so loud on his phone they threw us out!`,-1),c[46]||=n(`blockquote`,null,[n(`p`,null,`嗯，我们是！但是罗斯在电话里说得太大声了，他们把我们赶了出去！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`70.152`,duration:`3.624`}),c[47]||=a(),c[48]||=n(`strong`,null,`Ross Geller:`,-1),c[49]||=a(` I had to talk loud because the movie was loud!`,-1),c[50]||=n(`blockquote`,null,[n(`p`,null,`我不得不大声说话，因为电影太吵了！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`73.776`,duration:`2.232`}),c[51]||=a(),c[52]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[53]||=a(` (to Monica and Rachel) He's talking to London!`,-1),c[54]||=n(`blockquote`,null,[n(`p`,null,`（对莫妮卡和瑞秋）他在跟伦敦说话！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`76.008`,duration:`3.984`}),c[55]||=a(),c[56]||=n(`strong`,null,`Monica Geller:`,-1),c[57]||=a(` But why?! Did he get in touch with Emily?`,-1),c[58]||=n(`blockquote`,null,[n(`p`,null,`但是为什么？！他和艾米丽联系了吗？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`79.992`,duration:`7.776`}),c[59]||=a(),c[60]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[61]||=a(` Well no, not yet. He's calling everyone on her side of the family hoping that someone will help him get in touch with her.`,-1),c[62]||=n(`blockquote`,null,[n(`p`,null,`不，还没有。他打电话给她家里的每一个人，希望有人能帮助他与她取得联系。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`87.768`,duration:`4.992`}),c[63]||=a(),c[64]||=n(`strong`,null,`Ross Geller:`,-1),c[65]||=a(` (on phone) I-I-I don't care if I said some other girl's name you prissy, old twit!`,-1),c[66]||=n(`blockquote`,null,[n(`p`,null,`（在电话里）我，我，我不在乎我是否说了别的女孩的名字，你这个百里茜，老笨蛋！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`92.76`,duration:`4.104`}),c[67]||=a(),c[68]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[69]||=a(` Ross! Way to suck up to the family.`,-1),c[70]||=n(`blockquote`,null,[n(`p`,null,`罗斯！讨好家人的方式。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`96.864`,duration:`8.76`}),c[71]||=o(` <strong>Chandler Bing:</strong> (entering, happily, with a bottle of champagne, thinking that Monica is the only one there) Ha-ha-ha-(sees everyone)-enh-enh. I&#39;m so glad you guys are all here! My office finally got wrinkle free fax paper!<blockquote><p>（兴高采烈地端着一瓶香槟进来，心想莫妮卡是那里唯一的一个）哈哈哈-（见到大家）-恩恩恩。我很高兴你们都来了！我的办公室终于有了无皱纹的传真纸！</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, the next morning, Phoebe, Chandler, Ross, and Monica are eating breakfast.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，第二天早上，菲比、钱德勒、罗斯和莫妮卡正在吃早餐。</em></p></blockquote>`,9),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`105.624`,duration:`1.488`}),c[72]||=a(),c[73]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[74]||=a(` (entering, wearing a tux) Hey!`,-1),c[75]||=n(`blockquote`,null,[n(`p`,null,`（进来，穿着燕尾服）嘿！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`107.112`,duration:`6.24`}),c[76]||=a(),c[77]||=n(`strong`,null,`Chandler Bing:`,-1),c[78]||=a(` Oh no-no-no-no-no-no, vomit tux! No-no, vomit tux!`,-1),c[79]||=n(`blockquote`,null,[n(`p`,null,`哦，不，不，呕吐的礼服！不，不，吐燕尾服！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`113.352`,duration:`2.856`}),c[80]||=a(),c[81]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[82]||=a(` Don't worry, I had it dry-cleaned.`,-1),c[83]||=n(`blockquote`,null,[n(`p`,null,`别担心，我已经干洗过了。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`116.208`,duration:`5.784`}),c[84]||=a(),c[85]||=n(`strong`,null,`Monica Geller:`,-1),c[86]||=a(` Vomit tux? Who vomited on—y'know what, what you up to Joe?`,-1),c[87]||=n(`blockquote`,null,[n(`p`,null,`吐燕尾服？谁吐了你知道吗，你在跟乔干什么？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`121.992`,duration:`5.352`}),c[88]||=a(),c[89]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[90]||=a(` Well, I'm doing this telethon thing on TV and my agent got me a job as co-host!`,-1),c[91]||=n(`blockquote`,null,[n(`p`,null,`嗯，我在电视上做这个电视节目，我的经纪人给我找了份共同主持的工作！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`127.344`,duration:`1.944`}),c[92]||=a(),c[93]||=n(`strong`,null,`Monica Geller:`,-1),c[94]||=a(` Oh that's great!`,-1),c[95]||=n(`blockquote`,null,[n(`p`,null,`哦，太好了！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`129.288`,duration:`6.432`}),c[96]||=a(),c[97]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[98]||=a(` A little uh, good deed for PBS and a little TV exposure, now that's the kind of math Joey likes to do!`,-1),c[99]||=n(`blockquote`,null,[n(`p`,null,`一点，嗯，PBS的好事和一点电视曝光，这就是乔伊喜欢做的数学！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`135.72`,duration:`1.32`}),c[100]||=a(),c[101]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[102]||=a(` Ugh, PBS!`,-1),c[103]||=n(`blockquote`,null,[n(`p`,null,`啊，PBS！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`137.04`,duration:`2.496`}),c[104]||=a(),c[105]||=n(`strong`,null,`Monica Geller:`,-1),c[106]||=a(` What's wrong with PBS?`,-1),c[107]||=n(`blockquote`,null,[n(`p`,null,`PBS怎么了？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`139.536`,duration:`1.68`}),c[108]||=a(),c[109]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[110]||=a(` Ugh, what's right with them?`,-1),c[111]||=n(`blockquote`,null,[n(`p`,null,`呃，他们怎么了？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`141.216`,duration:`2.952`}),c[112]||=a(),c[113]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[114]||=a(` Why don’t you like PBS, Pheebs?`,-1),c[115]||=n(`blockquote`,null,[n(`p`,null,`菲比，你为什么不喜欢PBS？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`144.168`,duration:`14.064`}),c[116]||=a(),c[117]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[118]||=a(` Okay, 'cause right after my mom killed herself, I was just in this really bad place, y'know personally. So, I just thought that it'd make me feel better if I wrote to Sesame Street, 'cause they were so nice when I was a little kid! No one ever wrote back.`,-1),c[119]||=n(`blockquote`,null,[n(`p`,null,`好吧，因为就在我妈妈自杀之后，我就在这个非常糟糕的地方，你知道的。所以，我只是觉得如果我给芝麻街写信会让我感觉更好，因为我小时候他们都很好！没有人回信。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`158.232`,duration:`3.696`}),c[120]||=a(),c[121]||=n(`strong`,null,`Chandler Bing:`,-1),c[122]||=a(` Well y'know a lot of those Muppets don't have thumbs.`,-1),c[123]||=n(`blockquote`,null,[n(`p`,null,`你知道很多布偶都没有拇指。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`161.928`,duration:`6.456`}),c[124]||=a(),c[125]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[126]||=a(` All I got was a lousy key chain! And by that time I was living in a box. I didn't have keys!`,-1),c[127]||=n(`blockquote`,null,[n(`p`,null,`我得到的只是一个糟糕的钥匙链！那时我已经住在一个盒子里了。我没有钥匙！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`168.384`,duration:`7.248`}),c[128]||=a(),c[129]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[130]||=a(` I'm sorry Pheebs, I just, y'know, I just wanted to do a good deed. Like-like you did with the babies.`,-1),c[131]||=n(`blockquote`,null,[n(`p`,null,`对不起，菲比，我只是，你知道，我只是想做一件好事。就像你对待孩子一样。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`175.632`,duration:`5.184`}),c[132]||=a(),c[133]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[134]||=a(` This isn't a good deed, you just wanted to get on TV! This is totally selfish.`,-1),c[135]||=n(`blockquote`,null,[n(`p`,null,`这不是好事，你只是想上电视！这完全是自私的。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`180.816`,duration:`9.984`}),c[136]||=a(),c[137]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[138]||=a(` Whoa! Whoa! Whoa! What about you, having those babies for your brother? Talk about selfish!`,-1),c[139]||=n(`blockquote`,null,[n(`p`,null,`哇！哇！哇！那你呢，给你弟弟生孩子？说自私！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`190.8`,duration:`1.944`}),c[140]||=a(),c[141]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[142]||=a(` What-what are you talking about?!`,-1),c[143]||=n(`blockquote`,null,[n(`p`,null,`你在说什么？！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`192.744`,duration:`5.184`}),c[144]||=a(),c[145]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[146]||=a(` Well, yeah, it was a really nice thing and all, but it made you feel really good right?`,-1),c[147]||=n(`blockquote`,null,[n(`p`,null,`嗯，是的，这是一件非常好的事情，但它让你感觉非常好，对吗？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`197.928`,duration:`1.392`}),c[148]||=a(),c[149]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[150]||=a(` Yeah. So?`,-1),c[151]||=n(`blockquote`,null,[n(`p`,null,`是的。所以`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`199.32`,duration:`7.152`}),c[152]||=a(),c[153]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[154]||=a(` It made you feel good, so that makes it selfish. Look, there's no unselfish good deeds, sorry.`,-1),c[155]||=n(`blockquote`,null,[n(`p`,null,`它让你感觉很好，所以它很自私。听着，没有无私的善行，对不起。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`206.472`,duration:`3.888`}),c[156]||=a(),c[157]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[158]||=a(` Yes there are! There are totally good deeds that are selfless.`,-1),c[159]||=n(`blockquote`,null,[n(`p`,null,`是的，有！有完全无私的善行。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`210.36`,duration:`2.952`}),c[160]||=a(),c[161]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[162]||=a(` Well, may I ask for one example?`,-1),c[163]||=n(`blockquote`,null,[n(`p`,null,`我可以问一个例子吗？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`213.312`,duration:`2.952`}),c[164]||=a(),c[165]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[166]||=a(` Yeah, it's… Y'know there's—no you may not!`,-1),c[167]||=n(`blockquote`,null,[n(`p`,null,`是的，是……你知道，不，你不可以！`)],-1),c[168]||=n(`p`,null,[n(`em`,null,`(They are standing on either side of Chandler as they discuss the point. Chandler, meanwhile, is disgusted with the whole argument.)`)],-1),c[169]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（他们站在钱德勒一边讨论这一点。与此同时，钱德勒对整个争论感到厌恶。）`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`216.264`,duration:`3.048`}),c[170]||=a(),c[171]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[172]||=a(` That's because all people are selfish.`,-1),c[173]||=n(`blockquote`,null,[n(`p`,null,`那是因为所有人都是自私的。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`219.312`,duration:`2.088`}),c[174]||=a(),c[175]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[176]||=a(` Are you calling me selfish?!`,-1),c[177]||=n(`blockquote`,null,[n(`p`,null,`你说我自私吗？！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`221.4`,duration:`12.0`}),c[178]||=a(),c[179]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[180]||=a(` Are you calling you people? (Chandler rolls his eyes.) Yeah, well sorry to burst that bubble, Pheebs, but selfless good deeds don't exist. Okay? And you the deal on Santa Clause right?`,-1),c[181]||=n(`blockquote`,null,[n(`p`,null,`你是在给你们打电话吗？（钱德勒转动眼睛）是的，很抱歉打破了这个泡沫，菲比，但无私的善行是不存在的。可以你也同意圣诞老人条款，对吗？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`233.4`,duration:`4.944`}),c[182]||=a(),c[183]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[184]||=a(` I'm gonna find a selfless good dead. I'm gonna beat you, you evil genius.`,-1),c[185]||=n(`blockquote`,null,[n(`p`,null,`我会找到一个无私的好人。我要打败你，你这个邪恶的天才。`)],-1),c[186]||=n(`p`,null,[n(`em`,null,`(Ross's phone rings and he answers it.)`)],-1),c[187]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（罗斯的电话响了，他接了。）`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`238.344`,duration:`1.488`}),c[188]||=a(),c[189]||=n(`strong`,null,`Ross Geller:`,-1),c[190]||=a(` (on phone) Hello.`,-1),c[191]||=n(`blockquote`,null,[n(`p`,null,`（打电话）你好。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`239.832`,duration:`1.248`}),c[192]||=a(),c[193]||=n(`strong`,null,`Emily:`,-1),c[194]||=a(` (on phone from London) Hello, Ross?`,-1),c[195]||=n(`blockquote`,null,[n(`p`,null,`（从伦敦打来的电话）你好，罗斯？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`241.08`,duration:`13.272`}),c[196]||=a(),c[197]||=n(`strong`,null,`Ross Geller:`,-1),c[198]||=a(` Emily? Emily! Oh my God! Oh my God, it's Emily! (He picks up a lamp and hands it to Chandler, for no reason.) It's Emily everyone! Shush-shush-shhst! (to Emily) Hi!`,-1),c[199]||=n(`blockquote`,null,[n(`p`,null,`艾米丽？艾米丽！哦，我的上帝！天哪，是艾米丽！（他拿起一盏灯，无缘无故地递给钱德勒。）大家都是艾米丽！嘘嘘嘘嘘！（对艾米丽）嗨！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`254.352`,duration:`5.496`}),c[200]||=a(),c[201]||=n(`strong`,null,`Emily:`,-1),c[202]||=a(` Ross, I'm only ringing to say stop harassing my relatives. Good-bye!`,-1),c[203]||=n(`blockquote`,null,[n(`p`,null,`罗斯，我打电话只是想说别再骚扰我的亲戚了。再见！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`259.848`,duration:`12.552`}),c[204]||=a(),c[205]||=n(`strong`,null,`Ross Geller:`,-1),c[206]||=a(` No wait! Look, wait! Okay, you can hang up, but I'm gonna keep calling! I'm gonna, I'm gonna call everyone in England if that's what it takes to get you to talk to me!`,-1),c[207]||=n(`blockquote`,null,[n(`p`,null,`不，等等！看，等等！好的，你可以挂断，但我会继续打电话！我要，我要打电话给英格兰的每个人，如果你能和我说话的话！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`272.4`,duration:`1.8`}),c[208]||=a(),c[209]||=n(`strong`,null,`Emily:`,-1),c[210]||=a(` Really? About what?`,-1),c[211]||=n(`blockquote`,null,[n(`p`,null,`真的吗？关于什么？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`274.2`,duration:`9.696`}),c[212]||=a(),c[213]||=n(`strong`,null,`Ross Geller:`,-1),c[214]||=a(` Look you're my wife. We're-we're married. Y'know? I-I love you. I-I really miss you.`,-1),c[215]||=n(`blockquote`,null,[n(`p`,null,`看，你是我妻子。我们结婚了。你知道吗？我爱你。我真的很想你。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`283.896`,duration:`2.568`}),c[216]||=a(),c[217]||=n(`strong`,null,`Emily:`,-1),c[218]||=a(` I miss you to. Well, at least I think I do.`,-1),c[219]||=n(`blockquote`,null,[n(`p`,null,`我想念你。嗯，至少我想我是这样。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`286.464`,duration:`1.848`}),c[220]||=a(),c[221]||=n(`strong`,null,`Ross Geller:`,-1),c[222]||=a(` (to the gang, whispering) She's talking.`,-1),c[223]||=n(`blockquote`,null,[n(`p`,null,`（对那帮人耳语）她在说话。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`288.312`,duration:`0.768`}),c[224]||=a(),c[225]||=n(`strong`,null,`All:`,-1),c[226]||=a(` (subdued) Yay! (He motions for them to keep quiet, including Chandler who is still holding the lamp Ross handed him, before he goes off to talk to Emily in private.)`,-1),c[227]||=n(`blockquote`,null,[n(`p`,null,`（被制服）耶！（他示意他们保持安静，包括钱德勒，他仍然拿着罗斯递给他的灯，然后他就去和艾米丽私下谈话。）`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`289.08`,duration:`3.288`}),c[228]||=a(),c[229]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[230]||=a(` Hey, Joey, when you said the deal with Santa Clause, you meant?`,-1),c[231]||=n(`blockquote`,null,[n(`p`,null,`嘿，乔伊，当你说和圣诞老人的交易条款时，你的意思是？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`292.368`,duration:`2.352`}),c[232]||=a(),c[233]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[234]||=a(` That he doesn't exist.`,-1),c[235]||=n(`blockquote`,null,[n(`p`,null,`他根本不存在。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`294.72`,duration:`0.744`}),c[236]||=a(),c[237]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[238]||=a(` Right. (She turns and opens her eyes in shock.)`,-1),c[239]||=n(`blockquote`,null,[n(`p`,null,`对。（她转过身，震惊地睁开眼睛。）`)],-1),c[240]||=n(`hr`,null,null,-1),c[241]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Central Perk, Chandler, Monica, and Rachel are there.`)],-1),c[242]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`中央公园、钱德勒、莫妮卡和瑞秋在那里`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`295.464`,duration:`4.128`}),c[243]||=a(),c[244]||=n(`strong`,null,`Rachel Green:`,-1),c[245]||=a(` So Chandler, have you heard about Monica's secret boyfriend?`,-1),c[246]||=n(`blockquote`,null,[n(`p`,null,`钱德勒，你听说莫妮卡的秘密男友了吗？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`299.592`,duration:`6.528`}),c[247]||=a(),c[248]||=n(`strong`,null,`Chandler Bing:`,-1),c[249]||=a(` Uhh, yeah. She uh, she uh, she uh might've mentioned him.`,-1),c[250]||=n(`blockquote`,null,[n(`p`,null,`嗯，是的。她呃，她呃，她呃可能提到过他。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`306.12`,duration:`4.008`}),c[251]||=a(),c[252]||=n(`strong`,null,`Rachel Green:`,-1),c[253]||=a(` So Mon, when are we gonna meet this new secret waiter man?`,-1),c[254]||=n(`blockquote`,null,[n(`p`,null,`那么，妈妈，我们什么时候才能见到这个新来的秘密服务员？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`310.128`,duration:`6.024`}),c[255]||=a(),c[256]||=n(`strong`,null,`Monica Geller:`,-1),c[257]||=a(` Ohh, he's really shy. I-I don’t think he's up to meeting everyone yet.`,-1),c[258]||=n(`blockquote`,null,[n(`p`,null,`哦，他真的很害羞。我觉得他还没准备好见每个人。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`316.152`,duration:`3.6`}),c[259]||=a(),c[260]||=n(`strong`,null,`Chandler Bing:`,-1),c[261]||=a(` Yeah, I don't think he's up to meeting everyone yet.`,-1),c[262]||=n(`blockquote`,null,[n(`p`,null,`是啊，我想他还没准备好见每个人。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`319.752`,duration:`5.376`}),c[263]||=a(),c[264]||=n(`strong`,null,`Rachel Green:`,-1),c[265]||=a(` I don’t care! I wanna meet this guy who's the best sex she ever had!`,-1),c[266]||=n(`blockquote`,null,[n(`p`,null,`我不在乎！我想认识一个她有过的最好的性生活的男人！`)],-1),c[267]||=n(`p`,null,[n(`em`,null,`(Chandler is quite pleased with that statement.)`)],-1),c[268]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（钱德勒对此表示非常满意。）`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`325.128`,duration:`4.92`}),c[269]||=a(),c[270]||=n(`strong`,null,`Chandler Bing:`,-1),c[271]||=a(` Really?! That's what you heard? (To Monica) You said that?`,-1),c[272]||=n(`blockquote`,null,[n(`p`,null,`真的吗？！这就是你听到的？（对莫妮卡）你说的？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`330.048`,duration:`4.104`}),c[273]||=a(),c[274]||=n(`strong`,null,`Monica Geller:`,-1),c[275]||=a(` I might've said that. (Chandler laughs.) Why is that funny?`,-1),c[276]||=n(`blockquote`,null,[n(`p`,null,`我可能会这么说。（钱德勒笑着）为什么这么好笑？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`334.152`,duration:`5.352`}),c[277]||=a(),c[278]||=n(`strong`,null,`Chandler Bing:`,-1),c[279]||=a(` Because I'm very happy for him! (To Monica) And you, you lucky dog!`,-1),c[280]||=n(`blockquote`,null,[n(`p`,null,`因为我为他感到高兴！（对莫妮卡）还有你，你这个幸运儿！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`339.504`,duration:`1.44`}),c[281]||=a(),c[282]||=n(`strong`,null,`Ross Geller:`,-1),c[283]||=a(` (entering) Hi!`,-1),c[284]||=n(`blockquote`,null,[n(`p`,null,`（进来）嗨！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`340.944`,duration:`1.488`}),c[285]||=a(),c[286]||=n(`strong`,null,`Monica Geller:`,-1),c[287]||=a(` Hey!`,-1),c[288]||=n(`blockquote`,null,[n(`p`,null,`嘿！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`342.432`,duration:`3.624`}),c[289]||=a(),c[290]||=n(`strong`,null,`Ross Geller:`,-1),c[291]||=a(` Well, Emily's willing to work on the relationship.`,-1),c[292]||=n(`blockquote`,null,[n(`p`,null,`嗯，艾米丽愿意为这段关系努力。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`346.056`,duration:`1.56`}),c[293]||=a(),c[294]||=n(`strong`,null,`Chandler Bing:`,-1),c[295]||=a(` Yes!`,-1),c[296]||=n(`blockquote`,null,[n(`p`,null,`是的！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`347.616`,duration:`1.848`}),c[297]||=a(),c[298]||=n(`strong`,null,`Monica Geller:`,-1),c[299]||=a(` That's great!`,-1),c[300]||=n(`blockquote`,null,[n(`p`,null,`太好了！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`349.464`,duration:`1.728`}),c[301]||=a(),c[302]||=n(`strong`,null,`Ross Geller:`,-1),c[303]||=a(` In London!`,-1),c[304]||=n(`blockquote`,null,[n(`p`,null,`在伦敦！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`351.192`,duration:`1.464`}),c[305]||=a(),c[306]||=n(`strong`,null,`Monica Geller:`,-1),c[307]||=a(` What?!`,-1),c[308]||=n(`blockquote`,null,[n(`p`,null,`什么？！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`352.656`,duration:`2.616`}),c[309]||=a(),c[310]||=n(`strong`,null,`Ross Geller:`,-1),c[311]||=a(` She wants me to move to London.`,-1),c[312]||=n(`blockquote`,null,[n(`p`,null,`她想让我搬到伦敦去。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`355.272`,duration:`3.648`}),c[313]||=a(),c[314]||=n(`strong`,null,`Monica Geller:`,-1),c[315]||=a(` But you live here! (Ross rolls his eyes.) You know that.`,-1),c[316]||=n(`blockquote`,null,[n(`p`,null,`但你住在这里！（罗斯转动眼睛）你知道的。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`358.92`,duration:`2.376`}),c[317]||=a(),c[318]||=n(`strong`,null,`Rachel Green:`,-1),c[319]||=a(` What-what-what are you gonna do?`,-1),c[320]||=n(`blockquote`,null,[n(`p`,null,`你打算怎么办？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`361.296`,duration:`5.184`}),c[321]||=a(),c[322]||=n(`strong`,null,`Ross Geller:`,-1),c[323]||=a(` I bet if I talk to Carol and Susan I can convince them to move to London with Ben.`,-1),c[324]||=n(`blockquote`,null,[n(`p`,null,`我打赌如果我和卡萝和苏珊谈谈，我就能说服他们和本一起搬到伦敦。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`366.48`,duration:`7.104`}),c[325]||=a(),c[326]||=n(`strong`,null,`Monica Geller:`,-1),c[327]||=a(` Yeah, I'm sure your ex-wife will be more than happy to move to another country so you can patch things up with your new wife.`,-1),c[328]||=n(`blockquote`,null,[n(`p`,null,`是的，我相信你的前妻会非常乐意搬到另一个国家，这样你就可以和你的新妻子和好了。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`373.584`,duration:`1.848`}),c[329]||=a(),c[330]||=n(`strong`,null,`Ross Geller:`,-1),c[331]||=a(` It could happen.`,-1),c[332]||=n(`blockquote`,null,[n(`p`,null,`这是可能发生的。`)],-1),c[333]||=n(`hr`,null,null,-1),c[334]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Unitel Video, Studio 55, Joey's telethon, he is being shown around by the stage director.`)],-1),c[335]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`Unitel视频，55演播室，乔伊的电视节目，舞台导演带着他四处走动。`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`375.432`,duration:`5.232`}),c[336]||=a(),c[337]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[338]||=a(` (To the pledge volunteers) How ya doin'? Welcome. Good to see ya!`,-1),c[339]||=n(`blockquote`,null,[n(`p`,null,`（对志愿者们）你好吗？欢迎很高兴见到你！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`380.664`,duration:`1.248`}),c[340]||=a(),c[341]||=n(`strong`,null,`Stage Director:`,-1),c[342]||=a(` This will be your phone.`,-1),c[343]||=n(`blockquote`,null,[n(`p`,null,`这是你的电话。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`381.912`,duration:`5.352`}),c[344]||=a(),c[345]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[346]||=a(` That's great. But uh, I'm not really expecting a lot of calls.`,-1),c[347]||=n(`blockquote`,null,[n(`p`,null,`太好了。但是，呃，我并不期待有很多电话。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`387.264`,duration:`2.592`}),c[348]||=a(),c[349]||=n(`strong`,null,`Stage Director:`,-1),c[350]||=a(` No you answer it and take pledges.`,-1),c[351]||=n(`blockquote`,null,[n(`p`,null,`不，你回答并接受承诺。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`389.856`,duration:`2.04`}),c[352]||=a(),c[353]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[354]||=a(` But I'm the host!`,-1),c[355]||=n(`blockquote`,null,[n(`p`,null,`但我是主持人！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`391.896`,duration:`4.32`}),c[356]||=a(),c[357]||=n(`strong`,null,`Stage Director:`,-1),c[358]||=a(` No, Gary Collins is the host. You'll be answering the phones.`,-1),c[359]||=n(`blockquote`,null,[n(`p`,null,`不，加里·柯林斯是主持人。你会接电话的。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`396.216`,duration:`5.712`}),c[360]||=a(),c[361]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[362]||=a(` You don't seem to understand. See, I was Dr. Drake Remoray.`,-1),c[363]||=n(`blockquote`,null,[n(`p`,null,`你好像不明白。看，我是Drake Remoray医生。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`401.928`,duration:`2.064`}),c[364]||=a(),c[365]||=n(`strong`,null,`Stage Director:`,-1),c[366]||=a(` Well, here's your phone doctor. (She walks away.)`,-1),c[367]||=n(`blockquote`,null,[n(`p`,null,`嗯，这是你的电话医生。（她走开了。）`)],-1),c[368]||=n(`hr`,null,null,-1),c[369]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Monica and Rachel's, Phoebe, Rachel, and Monica are there.`)],-1),c[370]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`莫妮卡和瑞秋、菲比、瑞秋和莫妮卡在那里`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`403.992`,duration:`16.248`}),c[371]||=a(),c[372]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[373]||=a(` I cannot believe I can't find a selfless good deed! Y'know that old guy that lives next to me? Well, I snuck over there and-and raked up all the leaves on his front stoop. But he caught me and force-fed me cider and cookies. Then I felt wonderful. That old jackass!`,-1),c[374]||=n(`blockquote`,null,[n(`p`,null,`我不敢相信我找不到无私的善行！你认识住在我旁边的那个老家伙吗？嗯，我偷偷溜过去，把他门廊上所有的叶子都耙了起来。但他抓住我，强迫我喝苹果酒和饼干。然后我感觉好极了。那个老混蛋！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`420.24`,duration:`4.848`}),c[375]||=a(),c[376]||=n(`strong`,null,`Rachel Green:`,-1),c[377]||=a(` Maybe Joey's right. Maybe all good deeds are selfish.`,-1),c[378]||=n(`blockquote`,null,[n(`p`,null,`也许乔伊是对的。也许所有的好事都是自私的。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`425.088`,duration:`8.232`}),c[379]||=a(),c[380]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[381]||=a(` I will find a selfless good deed! 'Cause I just gave birth to three children and I will not let them be raised in a world where Joey is right!`,-1),c[382]||=n(`blockquote`,null,[n(`p`,null,`我会找到一件无私的善事因为我刚刚生了三个孩子，我不会让他们在乔伊是对的世界里长大！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`433.32`,duration:`4.656`}),c[383]||=a(),c[384]||=n(`strong`,null,`Chandler Bing:`,-1),c[385]||=a(` (entering) Hey, Monica? Can I ask you a cooking question?`,-1),c[386]||=n(`blockquote`,null,[n(`p`,null,`（进来）嘿，莫妮卡？我能问你一个烹饪问题吗？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`437.976`,duration:`1.608`}),c[387]||=a(),c[388]||=n(`strong`,null,`Monica Geller:`,-1),c[389]||=a(` Sure!`,-1),c[390]||=n(`blockquote`,null,[n(`p`,null,`当然！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`439.584`,duration:`6.0`}),c[391]||=a(),c[392]||=n(`strong`,null,`Chandler Bing:`,-1),c[393]||=a(` If you're cooking on the stove, does that mean that your new secret boyfriend is better in bed than Richard?`,-1),c[394]||=n(`blockquote`,null,[n(`p`,null,`如果你在炉子上做饭，这是否意味着你的新秘密男友在床上比理查德好？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`445.584`,duration:`3.024`}),c[395]||=a(),c[396]||=n(`strong`,null,`Rachel Green:`,-1),c[397]||=a(` Chandler! (Pause) Is he?`,-1),c[398]||=n(`blockquote`,null,[n(`p`,null,`钱德勒！（停顿）是吗？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`448.608`,duration:`5.808`}),c[399]||=a(),c[400]||=n(`strong`,null,`Monica Geller:`,-1),c[401]||=a(` Well, y'know I-I-I think I'm gonna respect the privacy of my new secret boyfriend.`,-1),c[402]||=n(`blockquote`,null,[n(`p`,null,`嗯，你知道，我想我会尊重我新的秘密男友的隐私。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`454.416`,duration:`8.424`}),c[403]||=a(),c[404]||=n(`strong`,null,`Chandler Bing:`,-1),c[405]||=a(` Why?! I mean if this guy was me and it was me who had learned that it was me who was the best you'd ever had, I'd be going like this. (He jumps up onto the table and starts doing his happy dance.)`,-1),c[406]||=n(`blockquote`,null,[n(`p`,null,`为什么？！我的意思是，如果这家伙是我，是我认识到是我是你有过的最好的人，我就会这样。（他跳到桌子上，开始跳起快乐的舞蹈。）`)],-1),c[407]||=n(`hr`,null,null,-1),c[408]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Ross's apartment, he's on the phone with Emily.`)],-1),c[409]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`罗斯的公寓，他正在和艾米丽通电话。`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`462.84`,duration:`6.336`}),c[410]||=a(),c[411]||=n(`strong`,null,`Ross Geller:`,-1),c[412]||=a(` All right Emily, as much as I love you, I'm sorry, I can't move to London without Ben.`,-1),c[413]||=n(`blockquote`,null,[n(`p`,null,`好吧，艾米丽，虽然我很爱你，但对不起，没有本我不能搬到伦敦。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`469.176`,duration:`1.8`}),c[414]||=a(),c[415]||=n(`strong`,null,`Emily:`,-1),c[416]||=a(` I understand that would be difficult.`,-1),c[417]||=n(`blockquote`,null,[n(`p`,null,`我知道那很难。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`470.976`,duration:`7.248`}),c[418]||=a(),c[419]||=n(`strong`,null,`Ross Geller:`,-1),c[420]||=a(` Yeah, would you please consider moving here? I mean you were gonna move here anyway, why can't you just do that?`,-1),c[421]||=n(`blockquote`,null,[n(`p`,null,`是的，你能考虑搬到这里吗？我是说你本来要搬来的，为什么你就不能这么做呢？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`478.224`,duration:`1.368`}),c[422]||=a(),c[423]||=n(`strong`,null,`Emily:`,-1),c[424]||=a(` I don't know, it's just…`,-1),c[425]||=n(`blockquote`,null,[n(`p`,null,`我不知道，只是…`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`479.592`,duration:`11.64`}),c[426]||=a(),c[427]||=n(`strong`,null,`Ross Geller:`,-1),c[428]||=a(` Oh-oh-okay, but-but I know, that even though I've been a-a complete idiot up 'til now, I mean, I mean you-you-you have to come here. You have to come here so we can work this out.`,-1),c[429]||=n(`blockquote`,null,[n(`p`,null,`哦，好吧，但我知道，尽管我到现在为止一直是个十足的白痴，我是说，我是说你必须来这里。你必须来这里，这样我们才能解决这个问题。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`491.232`,duration:`0.84`}),c[430]||=a(),c[431]||=n(`strong`,null,`Emily:`,-1),c[432]||=a(` All right.`,-1),c[433]||=n(`blockquote`,null,[n(`p`,null,`好的。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`492.072`,duration:`3.024`}),c[434]||=a(),c[435]||=n(`strong`,null,`Ross Geller:`,-1),c[436]||=a(` All right, did you just say all right?`,-1),c[437]||=n(`blockquote`,null,[n(`p`,null,`好吧，你刚才说好了吗？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`495.096`,duration:`2.04`}),c[438]||=a(),c[439]||=n(`strong`,null,`Emily:`,-1),c[440]||=a(` I did. Now I'm the idiot.`,-1),c[441]||=n(`blockquote`,null,[n(`p`,null,`是的。现在我是白痴了。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`497.136`,duration:`9.696`}),c[442]||=a(),c[443]||=n(`strong`,null,`Ross Geller:`,-1),c[444]||=a(` Oh, Emily that is, that is so great. It's gonna be so great! We're gonna be like-like-like two idiots in love!`,-1),c[445]||=n(`blockquote`,null,[n(`p`,null,`哦，艾米丽，那太好了。太棒了！我们会像两个白痴相爱！`)],-1),c[446]||=n(`p`,null,[n(`em`,null,`(She laughs.)`)],-1),c[447]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（她笑了。）`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`506.832`,duration:`3.168`}),c[448]||=a(),c[449]||=n(`strong`,null,`Emily:`,-1),c[450]||=a(` Ross, there's one thing that really scares me still.`,-1),c[451]||=n(`blockquote`,null,[n(`p`,null,`罗斯，还有一件事真的让我害怕。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`510.0`,duration:`2.208`}),c[452]||=a(),c[453]||=n(`strong`,null,`Ross Geller:`,-1),c[454]||=a(` Yes, tell me.`,-1),c[455]||=n(`blockquote`,null,[n(`p`,null,`是的，告诉我。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`512.208`,duration:`7.512`}),c[456]||=a(),c[457]||=n(`strong`,null,`Emily:`,-1),c[458]||=a(` Well, you have to understand how humiliating it was for me up on that altar in front of my entire family, all my friends.`,-1),c[459]||=n(`blockquote`,null,[n(`p`,null,`嗯，你必须明白，当着我整个家人、所有朋友的面站在祭坛上对我来说是多么丢脸。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`519.72`,duration:`4.416`}),c[460]||=a(),c[461]||=n(`strong`,null,`Ross Geller:`,-1),c[462]||=a(` I know. I am, I am so sorry.`,-1),c[463]||=n(`blockquote`,null,[n(`p`,null,`我知道。是的，我很抱歉。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`524.136`,duration:`5.184`}),c[464]||=a(),c[465]||=n(`strong`,null,`Emily:`,-1),c[466]||=a(` And then after decided to forgive you, seeing you at the airport catching our plane with her.`,-1),c[467]||=n(`blockquote`,null,[n(`p`,null,`后来我决定原谅你，在机场看到你和她一起赶飞机。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`529.32`,duration:`2.568`}),c[468]||=a(),c[469]||=n(`strong`,null,`Ross Geller:`,-1),c[470]||=a(` Again, very sorry.`,-1),c[471]||=n(`blockquote`,null,[n(`p`,null,`再次，非常抱歉。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`531.888`,duration:`7.8`}),c[472]||=a(),c[473]||=n(`strong`,null,`Emily:`,-1),c[474]||=a(` I mean, I can't-I can't be in the same room as her! It drives me mad just thinking of you being in the same room as her!`,-1),c[475]||=n(`blockquote`,null,[n(`p`,null,`我是说，我不能——我不能和她在同一个房间！一想到你和她在同一个房间，我就发疯了！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`539.688`,duration:`6.6`}),c[476]||=a(),c[477]||=n(`strong`,null,`Ross Geller:`,-1),c[478]||=a(` Emily, there is nothing between Rachel and me. Okay? I love you.`,-1),c[479]||=n(`blockquote`,null,[n(`p`,null,`艾米丽，我和瑞秋之间什么都没有。可以我爱你。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`546.288`,duration:`3.6`}),c[480]||=a(),c[481]||=n(`strong`,null,`Emily:`,-1),c[482]||=a(` All right. I'll come to New York and we'll try and make this work.`,-1),c[483]||=n(`blockquote`,null,[n(`p`,null,`好的。我会来纽约，我们会努力让这一切顺利进行。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`549.888`,duration:`3.936`}),c[484]||=a(),c[485]||=n(`strong`,null,`Ross Geller:`,-1),c[486]||=a(` Oh that is so great! That's…`,-1),c[487]||=n(`blockquote`,null,[n(`p`,null,`哦，太棒了！那是…`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`553.824`,duration:`2.328`}),c[488]||=o(` <strong>Emily:</strong> (interrupting him) As long as you don&#39;t see Rachel anymore.<blockquote><p>（打断他）只要你不再见到瑞秋。</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Ross is telling Phoebe, Monica, and Chandler about Emily&#39;s ultimatum.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，罗斯告诉菲比、莫妮卡和钱德勒艾米丽的最后通牒。</em></p></blockquote>`,9),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`556.152`,duration:`4.752`}),c[489]||=a(),c[490]||=n(`strong`,null,`Ross Geller:`,-1),c[491]||=a(` So I asked Emily if she would come to New York, and she said yes.`,-1),c[492]||=n(`blockquote`,null,[n(`p`,null,`所以我问艾米丽是否愿意来纽约，她说愿意。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`560.904`,duration:`1.56`}),c[493]||=a(),c[494]||=n(`strong`,null,`Chandler Bing:`,-1),c[495]||=a(` Yes!`,-1),c[496]||=n(`blockquote`,null,[n(`p`,null,`是的！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`562.464`,duration:`0.744`}),c[497]||=a(),c[498]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[499]||=a(` Ooh-ohh!`,-1),c[500]||=n(`blockquote`,null,[n(`p`,null,`哦哦！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`563.208`,duration:`1.536`}),c[501]||=a(),c[502]||=n(`strong`,null,`Monica Geller:`,-1),c[503]||=a(` Great!`,-1),c[504]||=n(`blockquote`,null,[n(`p`,null,`太好了！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`564.744`,duration:`5.112`}),c[505]||=a(),c[506]||=n(`strong`,null,`Ross Geller:`,-1),c[507]||=a(` No-no-no! Only if I promise never to see Rachel again.`,-1),c[508]||=n(`blockquote`,null,[n(`p`,null,`不，不！除非我保证再也见不到瑞秋。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`569.856`,duration:`0.72`}),c[509]||=a(),c[510]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[511]||=a(` Why?`,-1),c[512]||=n(`blockquote`,null,[n(`p`,null,`为什么？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`570.576`,duration:`4.056`}),c[513]||=a(),c[514]||=n(`strong`,null,`Monica Geller:`,-1),c[515]||=a(` What?! You can't—what did you tell her?`,-1),c[516]||=n(`blockquote`,null,[n(`p`,null,`什么？！你不能，你跟她说了什么？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`574.632`,duration:`9.144`}),c[517]||=a(),c[518]||=n(`strong`,null,`Ross Geller:`,-1),c[519]||=a(` I told her I'd have to think about it. I mean, how the hell am I supposed to make this kind of a decision? (They're all quiet.) I'm actually asking you!`,-1),c[520]||=n(`blockquote`,null,[n(`p`,null,`我告诉她我得考虑一下。我是说，我该怎么做这样的决定？（他们都很安静。）我真的在问你！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`583.776`,duration:`5.328`}),c[521]||=a(),c[522]||=n(`strong`,null,`Chandler Bing:`,-1),c[523]||=a(` Well, you can't just not see Rachel anymore, she's one of your best friends.`,-1),c[524]||=n(`blockquote`,null,[n(`p`,null,`你不能再不见瑞秋了，她是你最好的朋友之一。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`589.104`,duration:`5.88`}),c[525]||=a(),c[526]||=n(`strong`,null,`Monica Geller:`,-1),c[527]||=a(` Yeah! But, he can't not exactly see Emily, I mean that's his wife.`,-1),c[528]||=n(`blockquote`,null,[n(`p`,null,`是啊！但是，他不能完全看到艾米丽，我是说那是他的妻子。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`594.984`,duration:`0.6`}),c[529]||=a(),c[530]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[531]||=a(` Yeah.`,-1),c[532]||=n(`blockquote`,null,[n(`p`,null,`是的。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`595.584`,duration:`1.824`}),c[533]||=a(),c[534]||=n(`strong`,null,`Chandler Bing:`,-1),c[535]||=a(` That's true!`,-1),c[536]||=n(`blockquote`,null,[n(`p`,null,`没错！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`597.408`,duration:`4.848`}),c[537]||=a(),c[538]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[539]||=a(` Yeah, but you've known Rachel since High School and you cannot just cut her out of your life.`,-1),c[540]||=n(`blockquote`,null,[n(`p`,null,`是啊，但是你从高中就认识瑞秋了，你不能把她从你的生活中剪掉。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`602.256`,duration:`1.824`}),c[541]||=a(),c[542]||=n(`strong`,null,`Chandler Bing:`,-1),c[543]||=a(` That's true!`,-1),c[544]||=n(`blockquote`,null,[n(`p`,null,`没错！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`604.08`,duration:`2.232`}),c[545]||=a(),c[546]||=n(`strong`,null,`Monica Geller:`,-1),c[547]||=a(` No, you cannot.`,-1),c[548]||=n(`blockquote`,null,[n(`p`,null,`不，你不能。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`606.312`,duration:`3.144`}),c[549]||=a(),c[550]||=n(`strong`,null,`Ross Geller:`,-1),c[551]||=a(` Thanks for the help, problem solved. (Wipes his hands.)`,-1),c[552]||=n(`blockquote`,null,[n(`p`,null,`谢谢你的帮助，问题解决了。（他擦了擦手。）`)],-1),c[553]||=n(`p`,null,[n(`em`,null,`(The phone rings.)`)],-1),c[554]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（电话铃响了。）`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`609.456`,duration:`1.608`}),c[555]||=a(),c[556]||=n(`strong`,null,`Monica Geller:`,-1),c[557]||=a(` (answering it) Hello.`,-1),c[558]||=n(`blockquote`,null,[n(`p`,null,`（接电话）你好。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`611.064`,duration:`1.656`}),c[559]||=a(),c[560]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[561]||=a(` (on phone) Hey Mon!`,-1),c[562]||=n(`blockquote`,null,[n(`p`,null,`（打电话）嘿，妈妈！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`612.72`,duration:`5.784`}),c[563]||=a(),c[564]||=n(`strong`,null,`Monica Geller:`,-1),c[565]||=a(` Oh hey Joey! We've been watching all day, when are you gonna be on TV?`,-1),c[566]||=n(`blockquote`,null,[n(`p`,null,`哦，嘿，乔伊！我们看了一整天，你什么时候上电视？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`618.504`,duration:`6.144`}),c[567]||=a(),c[568]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[569]||=a(` See, there was kind of a mix up in my agent's office, but I'm still on TV and that's good exposure.`,-1),c[570]||=n(`blockquote`,null,[n(`p`,null,`看，我经纪人的办公室有点混乱，但我还在电视上，这是很好的曝光率。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`624.648`,duration:`2.136`}),c[571]||=a(),c[572]||=n(`strong`,null,`Monica Geller:`,-1),c[573]||=a(` (Looking at the TV) You're not on TV.`,-1),c[574]||=n(`blockquote`,null,[n(`p`,null,`（看着电视）你不在电视上。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`626.784`,duration:`3.72`}),c[575]||=a(),c[576]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[577]||=a(` Oh, uh, okay, how, how about now? (He waves his hand in front of the woman next to him and you can now see his arm on TV.)`,-1),c[578]||=n(`blockquote`,null,[n(`p`,null,`哦，嗯，好吧，现在怎么样？（他在旁边的女人面前挥手，你现在可以在电视上看到他的手臂。）`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`630.504`,duration:`4.248`}),c[579]||=a(),c[580]||=n(`strong`,null,`Chandler Bing:`,-1),c[581]||=a(` Hey, there he is! There he is!`,-1),c[582]||=n(`blockquote`,null,[n(`p`,null,`嘿，他来了！他在那儿！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`634.752`,duration:`1.992`}),c[583]||=a(),c[584]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[585]||=a(` Hello New York! (The woman bats his hand out of the way.)`,-1),c[586]||=n(`blockquote`,null,[n(`p`,null,`你好，纽约！（那个女人把他的手打到一边。）`)],-1),c[587]||=n(`hr`,null,null,-1),c[588]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Chandler and Joey's, the chick and the duck are watching Emeril Live, a cooking show.`)],-1),c[589]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`钱德勒和乔伊家，小鸡和小鸭正在看埃米尔现场烹饪节目。`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`636.744`,duration:`5.784`}),c[590]||=a(),c[591]||=n(`strong`,null,`Emeril:`,-1),c[592]||=a(` (on TV.) Now maybe you just like wanna but the whole duck in there! Who cares, y'know? Now I got the legs…`,-1),c[593]||=n(`blockquote`,null,[n(`p`,null,`（在电视上）现在也许你只是想，但是整个鸭子都在里面！谁在乎，你知道吗？现在我有了腿…`)],-1),c[594]||=n(`p`,null,[n(`em`,null,`(Chandler enters and sees what they're watching, panics, and runs to turn off the TV.)`)],-1),c[595]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（钱德勒进来看他们在看什么，惊慌失措，跑去关掉电视。）`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`642.528`,duration:`4.92`}),c[596]||=a(),c[597]||=n(`strong`,null,`Chandler Bing:`,-1),c[598]||=a(` How many times have I told you guys, you never watch the cooking channel!`,-1),c[599]||=n(`blockquote`,null,[n(`p`,null,`我告诉过你们多少次了，你们从来不看烹饪频道！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`647.448`,duration:`1.872`}),c[600]||=a(),c[601]||=n(`strong`,null,`Monica Geller:`,-1),c[602]||=a(` (entering) Hi Chandler.`,-1),c[603]||=n(`blockquote`,null,[n(`p`,null,`（进来）嗨，钱德勒。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`649.32`,duration:`1.44`}),c[604]||=a(),c[605]||=n(`strong`,null,`Chandler Bing:`,-1),c[606]||=a(` Hey!`,-1),c[607]||=n(`blockquote`,null,[n(`p`,null,`嘿！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`650.76`,duration:`4.824`}),c[608]||=a(),c[609]||=n(`strong`,null,`Monica Geller:`,-1),c[610]||=a(` Uh, listen, I need that broiling pan that Joey borrowed the other day.`,-1),c[611]||=n(`blockquote`,null,[n(`p`,null,`听着，我需要乔伊前几天借的烤盘。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`655.584`,duration:`6.624`}),c[612]||=a(),c[613]||=n(`strong`,null,`Chandler Bing:`,-1),c[614]||=a(` Oh that was yours? Uh, yeah, we used it when the duck was throwing up caterpillars.`,-1),c[615]||=n(`blockquote`,null,[n(`p`,null,`哦，那是你的？嗯，是的，我们在鸭子吐毛毛虫的时候用过。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`662.208`,duration:`4.248`}),c[616]||=a(),c[617]||=n(`strong`,null,`Monica Geller:`,-1),c[618]||=a(` William Sonoma, fall catalog, Page 27.`,-1),c[619]||=n(`blockquote`,null,[n(`p`,null,`威廉·索诺玛，秋季目录，第27页。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`666.456`,duration:`10.104`}),c[620]||=a(),c[621]||=n(`strong`,null,`Chandler Bing:`,-1),c[622]||=a(` Expect it in 4-6 weeks. (She starts to leave.) Umm, hey, umm, Joey's gonna be at the telethon for the rest of the day, we have the whole place to ourselves.`,-1),c[623]||=n(`blockquote`,null,[n(`p`,null,`预计在4-6周内。（她开始离开。）嗯，嘿，嗯，乔伊今天剩下的时间都在看电视节目，整个地方都是我们自己的。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`676.56`,duration:`1.944`}),c[624]||=a(),c[625]||=n(`strong`,null,`Monica Geller:`,-1),c[626]||=a(` Yeah, so?`,-1),c[627]||=n(`blockquote`,null,[n(`p`,null,`是的，那么？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`678.504`,duration:`5.088`}),c[628]||=a(),c[629]||=n(`strong`,null,`Chandler Bing:`,-1),c[630]||=a(` Well I just, thought maybe you'd wanna book some time with the best you'd ever had.`,-1),c[631]||=n(`blockquote`,null,[n(`p`,null,`嗯，我只是想，也许你会想和你有过的最好的朋友订一段时间。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`683.592`,duration:`4.296`}),c[632]||=a(),c[633]||=n(`strong`,null,`Monica Geller:`,-1),c[634]||=a(` Y'know what, champ? I think I'll pass.`,-1),c[635]||=n(`blockquote`,null,[n(`p`,null,`你知道吗，冠军？我想我会通过的。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`687.888`,duration:`1.464`}),c[636]||=a(),c[637]||=n(`strong`,null,`Chandler Bing:`,-1),c[638]||=a(` Why?`,-1),c[639]||=n(`blockquote`,null,[n(`p`,null,`为什么？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`689.352`,duration:`1.584`}),c[640]||=a(),c[641]||=n(`strong`,null,`Monica Geller:`,-1),c[642]||=a(` Why? (She hops into the living room and imitates Chandler's happy dance.)`,-1),c[643]||=n(`blockquote`,null,[n(`p`,null,`为什么？（她跳进客厅，模仿钱德勒的快乐舞蹈。）`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`690.936`,duration:`1.824`}),c[644]||=a(),c[645]||=n(`strong`,null,`Chandler Bing:`,-1),c[646]||=a(` What's your point?`,-1),c[647]||=n(`blockquote`,null,[n(`p`,null,`你的意思是什么？`)],-1),c[648]||=n(`hr`,null,null,-1),c[649]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`The Telethon, Joey's phone rings and he answers it.`)],-1),c[650]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`电视节目，乔伊的电话响了，他接了电话。`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`692.76`,duration:`2.304`}),c[651]||=a(),c[652]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[653]||=a(` (in a bored voice) PBS telethon.`,-1),c[654]||=n(`blockquote`,null,[n(`p`,null,`（用无聊的声音）PBS电视马拉松。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`695.064`,duration:`7.752`}),c[655]||=a(),c[656]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[657]||=a(` (on phone from Central Perk) Hey Joey, I just wanted to let you know that I found a selfless good deed. I just went down to the park and I let a bee sting me.`,-1),c[658]||=n(`blockquote`,null,[n(`p`,null,`嘿，乔伊，我只是想让你知道我发现了一件无私的好事。我刚去公园，就让一只蜜蜂蜇了我。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`702.816`,duration:`4.128`}),c[659]||=a(),c[660]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[661]||=a(` What?! What good is that gonna do anybody?`,-1),c[662]||=n(`blockquote`,null,[n(`p`,null,`什么？！这对任何人都有什么好处？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`706.944`,duration:`6.024`}),c[663]||=a(),c[664]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[665]||=a(` Well, it helps the bee look tough in front of his bee friends. The bee is happy and I am definitely not.`,-1),c[666]||=n(`blockquote`,null,[n(`p`,null,`嗯，这有助于蜜蜂在它的蜜蜂朋友面前显得坚强。蜜蜂是快乐的，而我绝对不是。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`712.968`,duration:`3.84`}),c[667]||=a(),c[668]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[669]||=a(` Now, y'know the bee probably died after he stung ya.`,-1),c[670]||=n(`blockquote`,null,[n(`p`,null,`现在，你知道那只蜜蜂可能是在叮了你之后死的。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`716.808`,duration:`1.128`}),c[671]||=a(),c[672]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[673]||=a(` (Thinks for a moment.) Aw, dammit! (Slams the phone down.)`,-1),c[674]||=n(`blockquote`,null,[n(`p`,null,`（想了想）噢，该死！（砰地关上电话。）`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`717.936`,duration:`2.28`}),c[675]||=a(),c[676]||=n(`strong`,null,`Stage Director:`,-1),c[677]||=a(` Back on in 30 seconds people!`,-1),c[678]||=n(`blockquote`,null,[n(`p`,null,`30秒后回来，大家！`)],-1),c[679]||=n(`p`,null,[n(`em`,null,`(Joey gets up and moves to the other end of his row to talk to the guy sitting there.)`)],-1),c[680]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（乔伊站起来，走到他那一排的另一端，和坐在那里的那个人说话。）`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`720.216`,duration:`3.672`}),c[681]||=a(),c[682]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[683]||=a(` Hey, excuse me, would you mind switching with me?`,-1),c[684]||=n(`blockquote`,null,[n(`p`,null,`嘿，对不起，你介意和我换一下吗？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`723.888`,duration:`2.64`}),c[685]||=a(),c[686]||=n(`strong`,null,`PBS Volunteer:`,-1),c[687]||=a(` Hey, no way, I'm in the shot man.`,-1),c[688]||=n(`blockquote`,null,[n(`p`,null,`PBS志愿者：嘿，不可能，我是枪手。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`726.528`,duration:`3.984`}),c[689]||=a(),c[690]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[691]||=a(` Come on man! You've been here all day!`,-1),c[692]||=n(`blockquote`,null,[n(`p`,null,`来吧，伙计！你一整天都在这里！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`730.512`,duration:`2.664`}),c[693]||=a(),c[694]||=n(`strong`,null,`PBS Volunteer:`,-1),c[695]||=a(` Yeah, I-I'm taking pledges here, eh?`,-1),c[696]||=n(`blockquote`,null,[n(`p`,null,`PBS志愿者：是的，我在这里接受承诺，嗯？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`733.176`,duration:`1.656`}),c[697]||=a(),c[698]||=n(`strong`,null,`Stage Director:`,-1),c[699]||=a(` We're on in 3, 2, (points to Gary Collins.)`,-1),c[700]||=n(`blockquote`,null,[n(`p`,null,`我们在第3、2节（指向加里·柯林斯）`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`734.832`,duration:`17.664`}),c[701]||=a(),c[702]||=n(`strong`,null,`Gary Collins:`,-1),c[703]||=a(` Welcome back to our fall telethon. Now if you've been enjoying the performance of Cirque Du Soleil, (As he is speaking, Joey and the volunteer getting into a shoving match.) and you'd like to see more of the same kind of programming, it's very simple. All you have to do (Joey is knocked down.) is call in your pledge and at that time tell the operator, one of our volunteers, what kind of programming you'd like to… (Just as the volunteer sits down, Joey pulls him to the ground.)`,-1),c[704]||=n(`blockquote`,null,[n(`p`,null,`欢迎回到我们的秋季电视节目。现在，如果你一直在欣赏太阳马戏团的表演，（正如他所说的，乔伊和志愿者正在进行一场推搡比赛。）并且你想看到更多类似的节目，这很简单。你所要做的就是（乔伊被撞倒了）打电话给你的承诺，然后告诉接线员，我们的一个志愿者，你想做什么样的节目…（就在志愿者坐下时，乔伊把他拉到地上。）`)],-1),c[705]||=n(`hr`,null,null,-1),c[706]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Monica and Rachel's, Monica and Phoebe are cooking, Chandler is reading a magazine.`)],-1),c[707]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`莫妮卡和瑞秋家，莫妮卡和菲比在做饭，钱德勒在看杂志。`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`752.496`,duration:`9.456`}),c[708]||=a(),c[709]||=n(`strong`,null,`Ross Geller:`,-1),c[710]||=a(` (entering) Okay, that's it. I cannot make this decision! It is too difficult, so I'm just gonna leave it entirely to the gods of fate. (He holds up and starts shaking a…)`,-1),c[711]||=n(`blockquote`,null,[n(`p`,null,`（进来）好了，就这样。我不能做这个决定！这太难了，所以我要把它完全交给命运之神。（他举起手来，开始摇晃……）`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`761.952`,duration:`6.216`}),c[712]||=a(),c[713]||=n(`strong`,null,`Monica Geller:`,-1),c[714]||=a(` A Magic Eight ball?! You can't be serious, you can't make this decision with a toy!`,-1),c[715]||=n(`blockquote`,null,[n(`p`,null,`一个神奇的八分球？！你不可能是认真的，你不能用玩具做决定！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`768.168`,duration:`1.464`}),c[716]||=a(),c[717]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[718]||=a(` Ooh, it's not a toy.`,-1),c[719]||=n(`blockquote`,null,[n(`p`,null,`哦，这不是玩具。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`769.632`,duration:`40.824`}),c[720]||=a(),c[721]||=n(`strong`,null,`Ross Geller:`,-1),c[722]||=a(` Well, I don't know what else to do. I mean, I either keep my wife and lose one of my-my-my best friends or I keep my friend and get divorced the second time before I'm 30! So-so if anyone has-has a better suggestion, let's hear it! 'Cause I-I got nothing! All right, don't be shy, any suggestion will do. (There are none.) Okay then. Here we go. Magic 8 Ball, should I never see Rachel again? (He turns it over and reads the answer) Ask again later. Later is not good enough. (He shakes it up again and reads the answer.) Ask again later. What the hell! This is broken! It-it is broken!`,-1),c[723]||=n(`blockquote`,null,[n(`p`,null,`嗯，我不知道还能做什么。我的意思是，我要么留下我的妻子，失去一个最好的朋友，要么留下我的朋友，在我30岁之前第二次离婚！所以，如果有人有更好的建议，让我们听听吧因为我什么都没有！好吧，别害羞，任何建议都行。（没有）那好吧。我们开始吧。魔幻8球，难道我再也见不到瑞秋了吗？（他把它翻过来读答案）过会儿再问。晚一点是不够的。（他再次摇晃并阅读答案）稍后再问。我勒个去！这个坏了！它坏了！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`810.456`,duration:`9.168`}),c[724]||=a(),c[725]||=n(`strong`,null,`Monica Geller:`,-1),c[726]||=a(` All right, let me see. (She grabs the 8 ball.) Will Chandler have sex tonight? (Reads the answer.) Don't count on it. Seems like it works to me.`,-1),c[727]||=n(`blockquote`,null,[n(`p`,null,`好吧，让我看看。（她抓住8号球）钱德勒今晚会做爱吗？（读着答案）别指望了。对我来说似乎很管用。`)],-1),c[728]||=n(`hr`,null,null,-1),c[729]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`The Telethon, Joey answers his ringing phone.`)],-1),c[730]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`电视节目，乔伊接电话。`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`819.624`,duration:`2.304`}),c[731]||=a(),c[732]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[733]||=a(` (in an unenthusiastic voice) PBS Telethon.`,-1),c[734]||=n(`blockquote`,null,[n(`p`,null,`（用冷淡的声音）PBS电视节目。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`821.928`,duration:`1.128`}),c[735]||=a(),c[736]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[737]||=a(` (on phone) Hi Joey.`,-1),c[738]||=n(`blockquote`,null,[n(`p`,null,`（打电话）嗨，乔伊。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`823.056`,duration:`1.872`}),c[739]||=a(),c[740]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[741]||=a(` Hey Pheebs!`,-1),c[742]||=n(`blockquote`,null,[n(`p`,null,`嘿，菲比！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`824.928`,duration:`4.464`}),c[743]||=a(),c[744]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[745]||=a(` I would like to make a pledge. I would like to donate $200.`,-1),c[746]||=n(`blockquote`,null,[n(`p`,null,`我想做个承诺。我想捐200美元。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`829.392`,duration:`7.56`}),c[747]||=a(),c[748]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[749]||=a(` $200? Are you sure Pheebs? I mean, after what Sesame Street did to ya?`,-1),c[750]||=n(`blockquote`,null,[n(`p`,null,`200美元？你确定菲比？我是说，在芝麻街对你做了什么之后？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`836.952`,duration:`11.256`}),c[751]||=a(),c[752]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[753]||=a(` Oh, I'm still mad at them but I also now that they bring happiness to lots of kids who's moms didn't kill themselves, so by supporting them, I'm doing a good thing, but I'm not happy about it. So there, a selfless good deed.`,-1),c[754]||=n(`blockquote`,null,[n(`p`,null,`哦，我还是很生他们的气，但我现在也很生气，因为他们给很多孩子带来了快乐，而他们的妈妈并没有自杀，所以通过支持他们，我做了一件好事，但我不高兴。这就是无私的善行。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`848.208`,duration:`3.456`}),c[755]||=a(),c[756]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[757]||=a(` And you don't a little good about donating the money?`,-1),c[758]||=n(`blockquote`,null,[n(`p`,null,`你对捐款一点也不在行吗？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`851.664`,duration:`3.624`}),c[759]||=a(),c[760]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[761]||=a(` No, it sucks. I was saving up to buy a hamster.`,-1),c[762]||=n(`blockquote`,null,[n(`p`,null,`不，糟透了。我在存钱买一只仓鼠。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`855.288`,duration:`4.536`}),c[763]||=a(),c[764]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[765]||=a(` A hamster? What, those things are like 10 bucks.`,-1),c[766]||=n(`blockquote`,null,[n(`p`,null,`一只仓鼠？什么，那些东西大概是10美元。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`859.824`,duration:`2.304`}),c[767]||=a(),c[768]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[769]||=a(` Yeah, not the one I had my eye on.`,-1),c[770]||=n(`blockquote`,null,[n(`p`,null,`是的，不是我看到的那个。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`862.128`,duration:`15.576`}),c[771]||=a(),c[772]||=n(`strong`,null,`Gary Collins:`,-1),c[773]||=a(` (on TV.) It looks like we have surpassed last year's pledge total! Thank you viewers! The pledge that did it was taken by one of our volunteers…(He walks over to where Joey is sitting.) Oh boy! And may I say one of our sharpest dressed volunteers, (Joey stands up.) Mr. Joseph Tribbiani!`,-1),c[774]||=n(`blockquote`,null,[n(`p`,null,`（在电视上）看起来我们已经超过了去年的承诺总数！谢谢观众!！做这件事的誓言是由我们的一位志愿者做的…（他走到乔伊坐的地方。）哦，天哪！我想说的是我们最讲究着装的志愿者之一，（乔伊站起来）约瑟夫·特里比亚尼先生！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`877.704`,duration:`7.704`}),c[775]||=a(),c[776]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[777]||=a(` Oh, look-look, Joey's on TV! Isn't that great? My pledge got Joey on TV! Oh that makes me feel—Oh no! (Realizes that her deed made her happy and therefore it's selfish and covers her mouth in horror.)`,-1),c[778]||=n(`blockquote`,null,[n(`p`,null,`哦，看，乔伊上电视了！那不是很棒吗？我的誓言让乔伊上了电视！哦，那让我觉得哦，不！（意识到她的行为使她快乐，因此这是自私的，并惊恐地捂住了嘴。）`)],-1),c[779]||=n(`hr`,null,null,-1),c[780]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Monica and Rachel's, later that day. Monica is coming out of the bathroom carrying her cleaning gear.`)],-1),c[781]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`莫妮卡和瑞秋家，那天晚些时候。莫妮卡带着清洁用具从浴室出来。`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`885.408`,duration:`9.888`}),c[782]||=a(),c[783]||=n(`strong`,null,`Chandler Bing:`,-1),c[784]||=a(` (entering) Look, maybe I got carried away before. But there's something you gotta know. If I'm the best, it's only because you've made me the best.`,-1),c[785]||=n(`blockquote`,null,[n(`p`,null,`（进来）看，也许我以前被迷住了。但有些事你必须知道。如果我是最好的，那只是因为你让我成为最好的。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`895.296`,duration:`1.824`}),c[786]||=a(),c[787]||=n(`strong`,null,`Monica Geller:`,-1),c[788]||=a(` Keep talking.`,-1),c[789]||=n(`blockquote`,null,[n(`p`,null,`继续说。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`897.12`,duration:`12.552`}),c[790]||=a(),c[791]||=n(`strong`,null,`Chandler Bing:`,-1),c[792]||=a(` I mean I was nothing before you. Call the other girls and ask. Which wouldn't take long. But when I'm with you, and we're together, OH…MY…GOD.`,-1),c[793]||=n(`blockquote`,null,[n(`p`,null,`我是说在你之前我什么都不是。给其他女孩打电话问问。这不会花很长时间。但是当我和你在一起，我们在一起的时候，哦…我的…上帝。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`909.672`,duration:`1.512`}),c[794]||=a(),c[795]||=n(`strong`,null,`Monica Geller:`,-1),c[796]||=a(` Really?`,-1),c[797]||=n(`blockquote`,null,[n(`p`,null,`真的吗？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`911.184`,duration:`11.712`}),c[798]||=a(),c[799]||=n(`strong`,null,`Chandler Bing:`,-1),c[800]||=a(` Oh-aw my God! Now, I understand if you never want to sleep with me again, but that would be wrong. We're too good! We owe it, to sex!`,-1),c[801]||=n(`blockquote`,null,[n(`p`,null,`哦，天哪！现在，我明白了，如果你再也不想和我上床，那就错了。我们太好了！我们欠它的，是性！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`922.896`,duration:`6.144`}),c[802]||=a(),c[803]||=n(`strong`,null,`Monica Geller:`,-1),c[804]||=a(` Well, if we owe it? (She throws down her cleaning stuff and jumps into his arms.) Oh my… When is Joey gonna be home?`,-1),c[805]||=n(`blockquote`,null,[n(`p`,null,`如果我们欠你的话？（她扔下清洁用品，跳到他的怀里。）噢，天哪……乔伊什么时候回家？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`929.04`,duration:`6.84`}),c[806]||=a(),c[807]||=n(`strong`,null,`Chandler Bing:`,-1),c[808]||=a(` Well, I was kinda hoping we could do this without him. (She starts to take off her latex gloves.) Oh no-no-no, leave the gloves on.`,-1),c[809]||=n(`blockquote`,null,[n(`p`,null,`嗯，我有点希望没有他我们也能做到。（她开始脱下她的乳胶手套。）哦，不，不，不要戴手套。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`935.88`,duration:`2.856`}),c[810]||=a(),c[811]||=n(`strong`,null,`Monica Geller:`,-1),c[812]||=a(` But, I just cleaned the bathroom.`,-1),c[813]||=n(`blockquote`,null,[n(`p`,null,`但是，我刚刚打扫了浴室。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`938.736`,duration:`3.024`}),c[814]||=a(),c[815]||=n(`strong`,null,`Chandler Bing:`,-1),c[816]||=a(` Yeah, why don't we lose the gloves.`,-1),c[817]||=n(`blockquote`,null,[n(`p`,null,`是啊，我们为什么不丢掉手套呢。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`941.76`,duration:`1.416`}),c[818]||=a(),c[819]||=n(`strong`,null,`Monica Geller:`,-1),c[820]||=a(` Yeah. (She takes them off.)`,-1),c[821]||=n(`blockquote`,null,[n(`p`,null,`是的。（她脱掉了。）`)],-1),c[822]||=n(`p`,null,[n(`em`,null,`(He carries her over to the door and opens it.)`)],-1),c[823]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（他把她抱到门口，打开了门。）`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`943.176`,duration:`3.216`}),c[824]||=a(),c[825]||=n(`strong`,null,`Chandler Bing:`,-1),c[826]||=a(` All right, let's show them how it's done.`,-1),c[827]||=n(`blockquote`,null,[n(`p`,null,`好吧，让我们让他们看看是怎么做的。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`946.392`,duration:`1.608`}),c[828]||=a(),c[829]||=n(`strong`,null,`Monica Geller:`,-1),c[830]||=a(` Okay.`,-1),c[831]||=n(`blockquote`,null,[n(`p`,null,`好的。`)],-1),c[832]||=n(`p`,null,[n(`em`,null,`(He starts to carry her into the hallway but hits her head on the door.)`)],-1),c[833]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（他开始把她抱进走廊，但她的头撞在了门上。）`)])],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`948.0`,duration:`1.416`}),c[834]||=a(),c[835]||=n(`strong`,null,`Monica Geller:`,-1),c[836]||=a(` Ow!`,-1),c[837]||=n(`blockquote`,null,[n(`p`,null,`噢！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`949.416`,duration:`2.376`}),c[838]||=a(),c[839]||=n(`strong`,null,`Chandler Bing:`,-1),c[840]||=a(` Y'know that wasn't part of it?`,-1),c[841]||=n(`blockquote`,null,[n(`p`,null,`你知道那不是其中的一部分吗？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`951.792`,duration:`1.584`}),c[842]||=o(` <strong>Monica Geller:</strong> I know!<blockquote><p>我知道！</p></blockquote><p><em>(He carries her into the hall.)</em></p><blockquote><p><em>（他把她抱进大厅。）</em></p></blockquote><hr><p>🎬 <em>Ross&#39;s apartment, Ross is prying at the Magic 8 Ball with a screwdriver as there&#39;s a knock on his door which he goes to answer.</em></p><blockquote><p>🎬 <em>罗斯的公寓，罗斯正在用螺丝刀撬魔法8号球，有人敲门，他去应门。</em></p></blockquote>`,9),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`953.376`,duration:`4.896`}),c[843]||=a(),c[844]||=n(`strong`,null,`Rachel Green:`,-1),c[845]||=a(` (entering) Hi! Are you ready? We're gonna be late!`,-1),c[846]||=n(`blockquote`,null,[n(`p`,null,`（进来）嗨！你准备好了吗？我们要迟到了！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`958.272`,duration:`1.608`}),c[847]||=a(),c[848]||=n(`strong`,null,`Ross Geller:`,-1),c[849]||=a(` For what?`,-1),c[850]||=n(`blockquote`,null,[n(`p`,null,`为了什么？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`959.88`,duration:`6.528`}),c[851]||=a(),c[852]||=n(`strong`,null,`Rachel Green:`,-1),c[853]||=a(` For Stella! Remember? She's gettin' her grove back in like 20 minutes.`,-1),c[854]||=n(`blockquote`,null,[n(`p`,null,`为了斯特拉！记得？她20分钟后就要回到她的小树林了。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`966.408`,duration:`9.12`}),c[855]||=a(),c[856]||=n(`strong`,null,`Ross Geller:`,-1),c[857]||=a(` Yeah, I uh, totally forgot about that. You mind if I take a rain check? I'm waiting for a call from Emily.`,-1),c[858]||=n(`blockquote`,null,[n(`p`,null,`是的，我完全忘记了。你介意我改天再去吗？我在等艾米丽的电话。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`975.528`,duration:`7.584`}),c[859]||=a(),c[860]||=n(`strong`,null,`Rachel Green:`,-1),c[861]||=a(` Sure. I guess. Hey, I hear you don't have to go to London. Yay!`,-1),c[862]||=n(`blockquote`,null,[n(`p`,null,`当然可以。我想是吧。嘿，我听说你不必去伦敦。耶！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`983.112`,duration:`4.176`}),c[863]||=a(),c[864]||=n(`strong`,null,`Ross Geller:`,-1),c[865]||=a(` It's not that easy, there's still a lot of relationship stuff.`,-1),c[866]||=n(`blockquote`,null,[n(`p`,null,`没那么容易，还有很多关系的东西。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`987.288`,duration:`1.728`}),c[867]||=a(),c[868]||=n(`strong`,null,`Rachel Green:`,-1),c[869]||=a(` Like what?`,-1),c[870]||=n(`blockquote`,null,[n(`p`,null,`像什么？`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`989.016`,duration:`4.656`}),c[871]||=a(),c[872]||=n(`strong`,null,`Ross Geller:`,-1),c[873]||=a(` Just stuff. Y'know kinda what Emily wants.`,-1),c[874]||=n(`blockquote`,null,[n(`p`,null,`只是一些东西。你知道艾米丽想要什么。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`993.672`,duration:`4.032`}),c[875]||=a(),c[876]||=n(`strong`,null,`Rachel Green:`,-1),c[877]||=a(` Well, why don't you talk to me about it, maybe I can help.`,-1),c[878]||=n(`blockquote`,null,[n(`p`,null,`嗯，你为什么不跟我谈谈，也许我能帮上忙。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`997.704`,duration:`8.496`}),c[879]||=a(),c[880]||=n(`strong`,null,`Ross Geller:`,-1),c[881]||=a(` No. No. You-you can't help. I mean, I kinda have to do this without your help.`,-1),c[882]||=n(`blockquote`,null,[n(`p`,null,`不，不，你帮不上忙。我是说，没有你的帮助，我不得不这么做。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`1006.2`,duration:`8.184`}),c[883]||=a(),c[884]||=n(`strong`,null,`Rachel Green:`,-1),c[885]||=a(` Well, I-I know you can do that too. I'm just, I'm just saying if you need somebody to talk to… Hi!`,-1),c[886]||=n(`blockquote`,null,[n(`p`,null,`我知道你也能做到。我只是，我只是说如果你需要找个人谈谈…嗨！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`1014.384`,duration:`1.608`}),c[887]||=a(),c[888]||=n(`strong`,null,`Ross Geller:`,-1),c[889]||=a(` Thanks.`,-1),c[890]||=n(`blockquote`,null,[n(`p`,null,`谢谢。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`1015.992`,duration:`24.72`}),c[891]||=a(),c[892]||=n(`strong`,null,`Rachel Green:`,-1),c[893]||=a(` Ross? Look, whatever this relationship stuff that Emily wants, just give it to her. Come on, the bottom line here is that you love her. So just fix whatever she wants fixed. Just do it. (The phone starts ringing.) I mean, you're gonna have to try. You'll just gonna hate yourself if you don't. (The phone keeps ringing.) Oh come on answer it! It's driving me crazy!`,-1),c[894]||=n(`blockquote`,null,[n(`p`,null,`罗斯？听着，不管Emily想要什么样的感情，只要给她就行了。来吧，这里的底线是你爱她。她想修什么就修什么。想做就做（电话铃响了。）我是说，你得试试。如果你不这样做，你会恨你自己的。（电话一直响。）哦，快接！这快把我逼疯了！`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`1040.712`,duration:`12.576`}),c[895]||=o(` <strong>Ross Geller:</strong> (answering the phone.) Hello. (Listens) Hi sweetie. (Listens.) Good. Look umm, yes I&#39;ve been thinking about that thing that you wanted me to do and, I can do it. (Rachel gives him a thumbs up.) So will you come to New York? (Rachel wants to know what she said, and he gives her a thumbs up and she goes over and hugs him. All the time not knowing what&#39;s going on.)<blockquote><p>（接电话）你好。（听）嗨，亲爱的。（听）好。听着，嗯，是的，我一直在想你要我做的事，我能做到。（瑞秋竖起大拇指）那你会来纽约吗？（瑞秋想知道她说了什么，他向她竖起大拇指，她走过去拥抱了他。一直不知道发生了什么。）</p></blockquote><p>Ending Credits</p><blockquote><p>期末学分</p></blockquote><hr><p>🎬 <em>Central Perk, ??????? is playing, as Chandler peaks his head out of the storage closet and sneaks back to his seat and pretends he&#39;s reading something. Then a short while later Monica pokes her head out of the closet and sneaks back to her seat and sits down, pretending as if nothing has happened.</em></p><blockquote><p>🎬 <em>中央公园正在播放，钱德勒从储物柜中探出头，偷偷回到座位上，假装在看什么。过了一会儿，莫妮卡探出头，偷偷回到座位上坐下，假装什么也没发生。</em></p></blockquote>`,9),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`1053.288`,duration:`2.304`}),c[896]||=a(),c[897]||=n(`strong`,null,`Monica Geller:`,-1),c[898]||=a(` Never done that before.`,-1),c[899]||=n(`blockquote`,null,[n(`p`,null,`以前从没这么做过。`)],-1),i(m,{src:`/audio/episodes/S05/S05E04.mp3`,start:`1055.592`,duration:`1.44`}),c[900]||=a(),c[901]||=n(`strong`,null,`Chandler Bing:`,-1),c[902]||=a(` Nope.`,-1),c[903]||=n(`blockquote`,null,[n(`p`,null,`没有。`)],-1),c[904]||=n(`p`,null,`contrl08.gif (14783 bytes)`,-1),c[905]||=n(`blockquote`,null,[n(`p`,null,`contrl08.gif（14783字节）`)],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};